package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextProductionInputs.Declaration;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.*;

/** Original X origins and exact member capabilities survive joint native witness replay. */
public final class ContextTrustedWitnessScopeRunner {
    static int checks,ids;static final int WORK=64000000,EVENTS=500000;
    static final String A="!@w seed(w,1)->mid(w,1);",B="!@w mid(w,1)->done(w,1);",OUT="!@w done(w,1)->out(w,1);",NEG="!@w done(w,1)->~flag(w,1);",WARM="!@w seed(w,1)->warm(w,1);";
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    interface Action{void run()throws Exception;}
    static void reject(Action a,String why)throws Exception{boolean seen=false;try{a.run();}catch(IllegalStateException|IllegalArgumentException e){seen=true;}require(seen,why);}
    static Snapshot bind(boolean local,String text)throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);require(m.compile(text,null,false),"native whole fixture");ContextProductionInventory inv=ContextProductionInventory.inspect(m,new UUID(0,++ids),1,local,Collections.emptyList(),1000);ContextProductionNativeBinding.Result r=ContextProductionNativeBinding.bind(m,inv,WORK,EVENTS);require(r.bound,"complete native snapshot: "+r.reason);return r.snapshot;}
    static ContextProductionFamilyAssembly.Artifact assemble(Snapshot x,List<Snapshot> foreign){ContextProductionFamilyAssembly.Result r=ContextProductionFamilyAssembly.assemble(x,foreign,WORK);require(r.assembled,"complete trusted witness plan: "+r.reason);return r.artifact;}
    static Item item(Packet p,String predicate){return p.items.stream().filter(v->v.atom.predicate.equals(predicate)&&v.atom.positive).findFirst().get();}
    static String base(boolean split){return split?"!$w seed(w,1); !$w flag(w,1);":"!$w seed(w,1)&&flag(w,1);";}
    static void origins(boolean split,boolean reverse,boolean duplicate)throws Exception{
        Snapshot x=bind(true,base(split)+" "+WARM+" "+OUT),a=bind(false,A),b=bind(false,B),alt=duplicate?bind(false,A):null;List<Snapshot> members=new ArrayList<>(Arrays.asList(a,b));if(duplicate)members.add(alt);if(reverse)Collections.reverse(members);Snapshot group=ContextProductionNativeBinding.trusted("own",members,WORK);ContextProductionFamilyAssembly.Artifact plan=assemble(x,Arrays.asList(group));ContextProductionFamilyAssembly.Evaluation e=plan.evaluate(16,16,WORK,EVENTS);require(e.status==ContextProductionFamilyAssembly.Status.FIXED_POINT,"trusted native fixed point: "+e.reason);Packet p=e.qualification.fixedPoint.packet;Item seed=item(p,"seed"),flag=item(p,"flag"),out=item(p,"out");
        Source seedSource=x.primary.stream().filter(v->v.bundle!=null&&v.statement.contains("seed(")).findFirst().get().source,outSource=x.primary.stream().filter(v->v.statement.equals(OUT)).findFirst().get().source;require(seed.atom.arguments.get(0).origin.source.equals(seedSource)&&seed.atom.arguments.get(0).origin.binder==0,"original whole X seed/binder");require(out.atom.arguments.get(0).origin.equals(seed.atom.arguments.get(0).origin),"out retains canonical seed origin across both member producers");require(split?!seed.atom.arguments.get(0).origin.equals(flag.atom.arguments.get(0).origin):seed.atom.arguments.get(0).origin.equals(flag.atom.arguments.get(0).origin),"same binder spelling in distinct bundles never aliases independent witnesses");
        Set<Set<Source>> expected=new HashSet<>();expected.add(new HashSet<>(Arrays.asList(seedSource,outSource,a.primary.get(0).source,b.primary.get(0).source)));if(duplicate)expected.add(new HashSet<>(Arrays.asList(seedSource,outSource,alt.primary.get(0).source,b.primary.get(0).source)));Set<Set<Source>> actual=new HashSet<>();for(Support proof:out.proofs){require(proof.depth==3&&expected.contains(proof.sources),"only necessary whole X/member Sources with exact cumulative depth");actual.add(proof.sources);}require(actual.equals(expected),"all identical-producer alternatives survive inside shared native replay");
        for(Item v:p.items)for(Slot slot:v.atom.arguments)if(slot.origin!=null)require(slot.origin.source.localX,"no foreign invented witness origin");
    }
    static void membership()throws Exception{
        Snapshot x=bind(true,base(false)+" "+WARM+" "+OUT),a=bind(false,A),b=bind(false,B),other=bind(false,"!@w seed(w,1)->alien(w,1);"),group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,b),WORK);ContextProductionFamilyAssembly.Artifact plan=assemble(x,Arrays.asList(group));Cut cut=Cut.of(group);List<Declaration> definitions=plan.plan.branches.stream().filter(v->!v.cut.localX).findFirst().get().declarations;Source source=a.primary.get(0).source;
        for(Source bad:Arrays.asList(other.primary.get(0).source,new Source(source.context,source.revision+1,source.rule,false,source.view),new Source(source.context,source.revision,source.rule,false,source.view+"changed")))try(ContextWitnessSeedReplay pass=ContextWitnessSeedReplay.open(plan.input,cut,WORK,EVENTS)){reject(()->pass.rule(bad,A),"outside member/revision/view rejected before native replay");require(!pass.inspect(16,WORK).reconstructed,"failed member frame cannot be reused as valid proof pass");}
        Snapshot wrong=ContextProductionNativeBinding.trusted("other",Arrays.asList(a,other),WORK);try(ContextWitnessSeedReplay pass=ContextWitnessSeedReplay.open(plan.input,cut,WORK,EVENTS)){for(Declaration d:definitions)pass.rule(d.source,d.statement);ContextWitnessResultTransport.Result r=ContextWitnessResultTransport.exportRoundNext(pass,Cut.of(wrong),definitions,16,WORK,EVENTS);require(!r.exported&&r.packet==null&&r.reason.contains("different sealed target"),"history from one complete member cut cannot certify another");}
        try(ContextWitnessSeedReplay legacy=ContextWitnessSeedReplay.open(plan.input,WORK,EVENTS)){for(Declaration d:definitions)legacy.rule(d.source,d.statement);require(!legacy.inspect(16,WORK).reconstructed,"legacy unscoped verifier retains its one-foreign-context restriction");}
        Snapshot emptyA=bind(false,""),emptyB=bind(false,"");Snapshot empty=ContextProductionNativeBinding.trusted("empty",Arrays.asList(emptyA,emptyB),WORK);require(ContextWitnessEmptyTarget.of(empty,()->{}).cut.members.size()==2,"empty proof retains every original member identity");reject(()->ContextWitnessEmptyTarget.of(group,()->{}),"nonempty group cannot masquerade as empty target");require(assemble(x,Arrays.asList(empty)).evaluate(16,16,WORK,EVENTS).status==ContextProductionFamilyAssembly.Status.FIXED_POINT,"empty shared target retains native X witness semantics");
        Snapshot privateWitness=bind(false,"!$w privateSeed(w,1);"),unsupported=ContextProductionNativeBinding.trusted("private",Arrays.asList(a,privateWitness),WORK);require(!ContextProductionFamilyAssembly.assemble(x,Arrays.asList(unsupported),WORK).assembled,"private foreign witness seed import remains explicitly unproved");
        Snapshot split=bind(true,base(true)+" "+WARM+" "+NEG);ContextProductionFamilyAssembly.Evaluation negative=assemble(split,Arrays.asList(group)).evaluate(16,16,WORK,EVENTS);require(negative.status==ContextProductionFamilyAssembly.Status.INCOMPLETE&&negative.refutations.isEmpty(),"independent flag witness yields no fabricated collision; uncovered negative consistency remains incomplete");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("trusted-witness-scope-").toString());for(boolean s:new boolean[]{false,true})for(boolean r:new boolean[]{false,true})for(boolean d:new boolean[]{false,true})origins(s,r,d);membership();System.out.println("CONTEXT_TRUSTED_WITNESS_SCOPE_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
